using System;
using System.Linq;
using System.Reflection;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Network.GamePackets;
using Console=System.Console;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshSubclassSnapshot(GameState p,GameState[] players){return Convert.ToString(Sql("SELECT json_build_object('prior',@prior::json,'classes',(SELECT json_agg(r ORDER BY uid) FROM subclasses r WHERE id=@uid),'study',(SELECT studypoints FROM entities WHERE uid=@uid))::text","prior",FreshJiangSnapshot(p,players),"uid",(long)p.Entity.UID));}
    static void FreshSubclassSave(GameState p,GameState[] players){foreach(var who in players)Require(EntityTable.SaveEntity(who));SkillTable.SaveSpells(p);Sql("UPDATE revora_fresh_subclass_probe SET snapshot=@snapshot","snapshot",FreshSubclassSnapshot(p,players));}
    static void FreshSubclassJourney(string phase){
        bool prepare=phase.EndsWith("prepare"),earn=phase.EndsWith("earn");var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w) && !w.Entity.Dead));

        Call(typeof(Revora.Database.JiangHu),"LoadClient",p);byte[] ids={1,2,3,4,5,6,9};uint[] materials={721259,721261,711188,723087,1088001,711679,723903};int[] counts={5,10,1,20,10,1,40},first={10922,11203,10924,10926,10920,10928,11201},last={10923,11204,10925,10927,10921,10929,11202};
        if(prepare){
            Require(FreshJiangSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_jiang_probe WHERE stage=2")) && (bool)Sql("SELECT to_regclass('revora_fresh_subclass_probe') IS NULL") && p.Entity.SubClasses.Classes.Count==0);
            int slots=Enumerable.Range(0,ids.Length).Max(n=>(counts[n]+Math.Max(1,(int)ConquerItemInformation.BaseInformations[materials[n]].StackSize)-1)/Math.Max(1,(int)ConquerItemInformation.BaseInformations[materials[n]].StackSize));int store=Math.Max(0,p.Inventory.Count-(40-slots));var bank=p.Warehouses[Revora.Game.ConquerStructures.Warehouse.WarehouseID.BirdCity];Require(bank.Count+store<=60 && p.Inventory.Objects.Count(i=>i.Days==0)>=store);
            if(store>0){FreshClassicTalk(p,1015,10027,0);foreach(var item in p.Inventory.Objects.Where(i=>i.Days==0).Take(store).ToArray()){var frame=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,frame);Revora.Network.Writer.WriteUInt16(1102,2,frame);Revora.Network.Writer.WriteUInt32(10027,4,frame);frame[12]=1;frame[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,frame);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,frame);Warehouse.Process(frame,p);Require(!p.Inventory.ContainsUID(item.UID) && bank.ContainsUID(item.UID));}}Require(p.Inventory.Count<=40-slots);p.Entity.Teleport(1002,424,339);
            Sql("CREATE TABLE revora_fresh_subclass_probe(stage int,cp_spent bigint,books int,spent_study bigint,initial_study bigint,snapshot text);INSERT INTO revora_fresh_subclass_probe VALUES(0,0,0,0,@study,NULL)","study",(long)p.Entity.SubClasses.StudyPoints);FreshSubclassSave(p,players);Console.WriteLine("[fresh-subclass] initial-study="+p.Entity.SubClasses.StudyPoints+" bird-stored="+store+" maximum-enrollment-slots="+slots);
        }else{
            Require(FreshSubclassSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_subclass_probe")));
            if(earn){
                Require((int)Sql("SELECT stage FROM revora_fresh_subclass_probe")==0);int completed=0;var timer=System.Diagnostics.Stopwatch.StartNew();
                foreach(byte id in ids){if(p.Entity.SubClasses.Classes.ContainsKey(id) && p.Entity.SubClasses.Classes[id].Level==9 && p.Entity.SubClasses.Classes[id].Phase==9)continue;if(completed>=2 || timer.Elapsed.TotalSeconds>=180)break;uint startingCp=p.Entity.ConquerPoints;int index=Array.IndexOf(ids,id);
                    if(!p.Entity.SubClasses.Classes.ContainsKey(id)){uint type=materials[index];int owned=p.Inventory.Objects.Where(i=>i.ID==type && i.Lock==0).Sum(i=>Math.Max(1,(int)i.StackSize)),needed=Math.Max(0,counts[index]-owned);if(needed>0){uint cp=p.Entity.ConquerPoints;CareerSubclassBuy(p,type,(uint)needed);Sql("UPDATE revora_fresh_subclass_probe SET cp_spent=cp_spent+@cp","cp",(long)(cp-p.Entity.ConquerPoints));}int before=p.Inventory.Objects.Where(i=>i.ID==type).Sum(i=>Math.Max(1,(int)i.StackSize));CareerSubclassRequest(p,9,id);Require(p.Entity.SubClasses.Classes.ContainsKey(id) && p.Entity.SubClasses.Classes[id].Level==1 && p.Entity.SubClasses.Classes[id].Phase==1 && p.Inventory.Objects.Where(i=>i.ID==type).Sum(i=>Math.Max(1,(int)i.StackSize))==before-counts[index]);FreshSubclassSave(p,players);string once=FreshSubclassSnapshot(p,players);CareerSubclassRequest(p,9,id);Require(once==FreshSubclassSnapshot(p,players));}
                    while(p.Entity.SubClasses.Classes[id].Level<9){byte level=p.Entity.SubClasses.Classes[id].Level;ushort cost=(ushort)Call(Feature("SubclassProgression"),"Cost",id,level);Require(cost>0);
                        while(p.Entity.SubClasses.StudyPoints<cost){var book=p.Inventory.Objects.FirstOrDefault(i=>i.ID==723342);if(book==null){uint cp=p.Entity.ConquerPoints;uint count=(uint)((cost-p.Entity.SubClasses.StudyPoints+499)/500);CareerSubclassBuy(p,723342,count);Sql("UPDATE revora_fresh_subclass_probe SET cp_spent=cp_spent+@cp","cp",(long)(cp-p.Entity.ConquerPoints));book=p.Inventory.Objects.First(i=>i.ID==723342);}ushort before=p.Entity.SubClasses.StudyPoints,stack=book.StackSize;ItemHandler.UseItem(book,p);Require(p.Entity.SubClasses.StudyPoints==before+500 && (stack==1?!p.Inventory.ContainsUID(book.UID):book.StackSize==stack-1));Sql("UPDATE revora_fresh_subclass_probe SET books=books+1");FreshSubclassSave(p,players);}
                        ushort study=p.Entity.SubClasses.StudyPoints;CareerSubclassRequest(p,2,id);Require(p.Entity.SubClasses.Classes[id].Level==level+1 && p.Entity.SubClasses.StudyPoints==study-cost);Sql("UPDATE revora_fresh_subclass_probe SET spent_study=spent_study+@cost","cost",(long)cost);FreshSubclassSave(p,players);
                    }
                    while(p.Entity.SubClasses.Classes[id].Phase<9){byte phaseBefore=p.Entity.SubClasses.Classes[id].Phase;CareerSubclassRequest(p,10,id);Require(p.Entity.SubClasses.Classes[id].Phase==phaseBefore+1);FreshSubclassSave(p,players);}string maxed=FreshSubclassSnapshot(p,players);CareerSubclassRequest(p,9,id);CareerSubclassRequest(p,2,id);CareerSubclassRequest(p,10,id);Require(maxed==FreshSubclassSnapshot(p,players));completed++;Console.WriteLine("[fresh-subclass] mastered="+id+" cp="+(startingCp-p.Entity.ConquerPoints)+" study="+p.Entity.SubClasses.StudyPoints);
                }
                if(ids.All(id=>p.Entity.SubClasses.Classes.ContainsKey(id) && p.Entity.SubClasses.Classes[id].Level==9 && p.Entity.SubClasses.Classes[id].Phase==9))Sql("UPDATE revora_fresh_subclass_probe SET stage=1");FreshSubclassSave(p,players);
            }else{
                Require(phase.EndsWith("reload") && (int)Sql("SELECT stage FROM revora_fresh_subclass_probe")==1);
                foreach(byte id in ids){Require(p.Entity.SubClasses.Classes[id].Level==9 && p.Entity.SubClasses.Classes[id].Phase==9);int index=Array.IndexOf(ids,id);foreach(int achievement in new[]{first[index],last[index]})Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id=@id AND source='subclass-v1'","uid",(long)p.Entity.UID,"id",achievement)==1);string saved=FreshSubclassSnapshot(p,players);CareerSubclassRequest(p,9,id);CareerSubclassRequest(p,2,id);CareerSubclassRequest(p,10,id);Require(saved==FreshSubclassSnapshot(p,players));}for(ushort dance=1415;dance<=1423;dance++)Require(p.Spells.ContainsKey(dance));
                foreach(var bank in p.Warehouses){var stored=(long[])Sql("SELECT coalesce(array_agg(uid ORDER BY uid),ARRAY[]::bigint[]) FROM items WHERE entityid=@uid AND warehouse=@bank","uid",(long)p.Entity.UID,"bank",(long)(uint)bank.Key);Require(stored.Length==bank.Value.Count && stored.All(id=>bank.Value.ContainsUID((uint)id)));}
                foreach(var who in players){var stored=(long[])Sql("SELECT coalesce(array_agg(uid ORDER BY uid),ARRAY[]::bigint[]) FROM items WHERE entityid=@uid AND position=0 AND warehouse=0 AND coalesce(inwardrobe,0)=0","uid",(long)who.Entity.UID);Require(stored.SequenceEqual(who.Inventory.Objects.Select(i=>(long)i.UID).OrderBy(id=>id)));}
            }
            Require((long)p.Entity.SubClasses.StudyPoints==Convert.ToInt64(Sql("SELECT initial_study+books*500-spent_study FROM revora_fresh_subclass_probe")) && FreshSubclassSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_subclass_probe")));
        }
        Require(!PirateFenced(p));Console.WriteLine("[career-process] "+phase+"-passed stage="+Sql("SELECT stage FROM revora_fresh_subclass_probe")+" books="+Sql("SELECT books FROM revora_fresh_subclass_probe")+" spent-study="+Sql("SELECT spent_study FROM revora_fresh_subclass_probe")+" cp="+Sql("SELECT cp_spent FROM revora_fresh_subclass_probe"));Console.Out.Flush();if(prepare || earn){Environment.Exit(0);return;}Server.CommandsAI("@close");throw new InvalidOperationException("Fresh subclasses did not close.");
    }
}
